// golfing 961 chars old version of "Recursive Penrose Tiling" by shadertoyjiang. https://shadertoy.com/view/l3cBz8
// more readable version at the end


// --- getting obfuscated :-)

#define L(b)       length( u-c - (b) * clamp( dot(u-c,b)/dot(b,b), 0., 1.) )//
#define S(d,e,f)   A=d, B=e, C=f, a=A, b=B, c=C//
#define C(a,b,d) ( (a-d)*(b-d).x - (a-d).x*(b-d) ).y// 
#define c(a,b,d)   C(a,b,d) * C(u,b,d) > 0. ? S

void mainImage(out vec4 o, vec2 U)
{
    float G = .618, l = 5.;
    vec2  R = iResolution.xy,
          u = ( U+U - R ) / R.y,
          d, e, A, B, C,
          a = -vec2(l,1), b = vec2(l,-1), c; c.y = l*.727 -1.; //tan(PI/5.)

    for( int T, i; i++ < 8; ) 
        if ( T < 1 )  // changing this to ().: bugs on windows
            d = a + (b - a) * G,
            e = a + (c - a) * G,
            T = c(a,e,d) (d,a,e), 0
              : c(b,c,d) (b,c,d), 0
              :       ( S(e,c,d), 1 );
          else
            d = c + (a - c) * G,
            T = c(a,d,b) (d,a,b), 1
              :       ( S(b,c,d), 0 );   

    o =  1. - R.yyyy/4.* min( L(a-c), L(b-c) );
}





