/** // --- 564 chars

#define L(b)     length(u - b * clamp(dot(u,b)/dot(b,b), 0., 1.))
#define S(d,e,f) A = d, B = e, C = f, a = A, b = B, c= C
#define cro(a,b,d) ( (a-d).y*(b-d).x - (a-d).x*(b-d).y ) 

void mainImage(out vec4 o, vec2 U)
{
    vec2 R = iResolution.xy,
         u = (U+U - R) / R.y,
         a, b, c, d, e ,A, B, C, n1, n2;

    float G = .618, l = 5.;

    a = vec2(-l, -1), b = vec2(l, -1), c = vec2(0, -1.+l*.727); //tan(PI/5.))

    for(int T=1, i; i<8; i++) 
    {
        if(T==1)
        {
            d = a + (b - a) * G;
            e = a + (c - a) * G;
            T = cro(a,e,d) * cro(u,e,d) > 0. ? S(d,a,e), 1
              : cro(b,c,d) * cro(u,c,d) > 0. ? S(b,c,d), 1
              :                              ( S(e,c,d), 2 );
        }else{
            d = c + (a - c) * G;
            T = cro(a,d,b) * cro(u,d,b) > 0. ? S(d,a,b), 2
              :                              ( S(b,c,d), 1 );

        }
    }
    u -= c;
    o = vec4( 1.1 - 1e2* min( L((a-c)), L((b-c)) ) );
}





/** // --- 658 chars

#define L(b)     length(u - b * clamp(dot(u,b)/dot(b,b), 0., 1.))
#define S(d,e,f) newa = d, newb = e, newc = f, a = newa, b = newb, c= newc

void mainImage(out vec4 o, vec2 U)
{
    vec2 R = iResolution.xy,
         u = (U+U - R) / R.y,
         a, b, c, d, e ,newa, newb, newc, n1, n2;

    float f1,f2, G = .618, l = 5.; // bdlen

    a = vec2(-l, -1), b = vec2(l, -1), c = vec2(0, -1.+l*.727); //tan(PI/5.))

    for(int T=1, i; i<8; i++) 
    {
        if(T==1)
        {
            d = a + (b - a) * G;
            e = a + (c - a) * G;
            n1 = (e-d).yx * vec2(-1,1);
            n2 = (c-d).yx * vec2(-1,1);
            f1 = dot(a-d, n1)*dot(u - d, n1);
            f2 = dot(b-d, n2)*dot(u - d, n2);
            if     (f1>0.) S(d,a,e), T=1;
            else if(f2>0.) S(b,c,d), T=1;
            else           S(e,c,d), T=2;
        } else {
            d = c + (a - c) * G;
            n1 = (d-b).yx * vec2(-1,1);
            if(dot(a-b, n1)*dot(u-b, n1)>0.) S(d,a,b), T=2;
            else                             S(b,c,d), T=1;

        }
    }
    u -= c;
    o = vec4( 1.1 - 1e2* min(L((a-c)), L((b-c))) );
}

